// ---------- Helper accessors ----------

export function getDepartmentsForIndustry(industryId: number): JobDepartment[] {
  return JOB_DEPARTMENTS.filter((d) => d.industry_id === industryId);
}

export function getRolesForDepartment(departmentId: number): JobRole[] {
  return JOB_ROLES.filter((r) => r.department_id === departmentId);
}

export function getRolesForIndustry(industryId: number): JobRole[] {
  return JOB_ROLES.filter((r) => r.industry_id === industryId);
}

export function getIndustryBySlug(slug: string): JobIndustry | undefined {
  return JOB_INDUSTRIES.find((i) => i.slug === slug);
}

export function getDepartmentBySlug(slug: string): JobDepartment | undefined {
  return JOB_DEPARTMENTS.find((d) => d.slug === slug);
}

export function getRoleBySlug(slug: string): JobRole | undefined {
  return JOB_ROLES.find((r) => r.slug === slug);
}

export function getRoleByName(name: string): JobRole | undefined {
  return JOB_ROLES.find((r) => r.name.toLowerCase() === name.toLowerCase());
}

// Flat list of ALL role names — used for search dropdowns / candidate skill
// picker where a simple flat searchable list (not the nested tree) is needed.
export function getAllRoleNames(): string[] {
  return JOB_ROLES.map((r) => r.name);
}

// Verified counts (see SUPABASE_HIERARCHY_VALIDATION notes / build script).
export const TOTAL_INDUSTRIES = JOB_INDUSTRIES.length;
export const TOTAL_DEPARTMENTS = JOB_DEPARTMENTS.length;
export const TOTAL_JOB_ROLES = JOB_ROLES.length;
